"""Build the group generated by the round-2 spread-stabiliser symmetries of W(11) (syms.json) and save its elements."""
import json, numpy as np, sys, time
R2 = '/home/user/degree-diameter/research/squads/gqd5-r2/c2/'
gens = [np.array(p, dtype=np.int32) for p in json.load(open(R2 + 'syms.json'))['perms']]
n = len(gens[0])
ident = np.arange(n, dtype=np.int32)
def key(p): return p.tobytes()
elems = {key(ident): ident}
frontier = [ident]
t0 = time.time()
while frontier:
    nf = []
    for g in frontier:
        for s in gens:
            h = s[g]          # composition s after g
            k = key(h)
            if k not in elems:
                elems[k] = h; nf.append(h)
                if len(elems) > 200000:
                    sys.exit('group too large')
    frontier = nf
print('group order', len(elems), 'time', round(time.time()-t0, 1), flush=True)
G = np.array(list(elems.values()), dtype=np.int16)
np.save('/home/user/degree-diameter/research/squads/gqd5-r3/c2/group.npy', G)
